package org.sleepwell.app;

import android.app.*;
import android.content.*;
import android.os.*;
import android.view.*;
import android.widget.*;
import java.time.*;

/** Vendor-source charts are intentionally separate from SleepWell phone/sonar measurement graphs. */
public final class SleepCsvSourceActivity extends Activity implements SleepCsvSourceJob.Observer {
    private SleepCsvSourceJob job;private int movementPage,noisePage,movementSelected=-1,noiseSelected=-1,eventPage,timelinePage,intervalPage;private boolean timelineFull=true,resumed;private String sourceHash="";private Dialog detail;
    static Intent intent(Activity owner,long session){return new Intent(owner,SleepCsvSourceActivity.class).putExtra("record",session);}
    @Override public void onCreate(Bundle state){super.onCreate(state);RecordUi.review(this);if(state!=null){movementPage=state.getInt("movementPage");noisePage=state.getInt("noisePage");movementSelected=state.getInt("movementSelected",-1);noiseSelected=state.getInt("noiseSelected",-1);eventPage=state.getInt("eventPage");timelinePage=state.getInt("timelinePage");intervalPage=state.getInt("intervalPage");timelineFull=state.getBoolean("timelineFull",true);sourceHash=state.getString("sourceHash","");}Object retained=getLastNonConfigurationInstance();job=retained instanceof SleepCsvSourceJob?(SleepCsvSourceJob)retained:new SleepCsvSourceJob(getApplicationContext(),getIntent().getLongExtra("record",0));if(Build.VERSION.SDK_INT>=33)getOnBackInvokedDispatcher().registerOnBackInvokedCallback(android.window.OnBackInvokedDispatcher.PRIORITY_DEFAULT,this::back);job.observe(this);}
    @Override public Object onRetainNonConfigurationInstance(){return job;}
    @Override protected void onResume(){super.onResume();if(resumed&&!job.busy())job.load();resumed=true;}
    public void changed(){if(isDestroyed())return;SleepCsvSourceJob.Data data=job.data;if(data!=null&&!sourceHash.equals(data.source.sha256)){sourceHash=data.source.sha256;movementPage=noisePage=eventPage=timelinePage=intervalPage=0;movementSelected=noiseSelected=-1;}LinearLayout body=Design.page(this,false,null,n->{});RecordUi.label(this,body);RecordUi.header(body,"Imported source signals",this::back);
        if(job.phase==SleepCsvSourceJob.Phase.LOADING){Design.space(body,24);Design.text(body,"Reading original CSV signals…",16,500,Design.MUTED);return;}if(data==null){Design.space(body,28);Design.text(body,"Source signals unavailable",22,600,Design.INK);Design.space(body,10);Design.text(body,job.message,14,400,Design.MUTED);Design.button(body,"Try again",true,job::load);return;}
        SleepCsvFormat.Entry entry=data.source;ZoneId zone=ZoneId.of(entry.zone);Design.space(body,10);Design.text(body,RecordUi.date(entry.start,zone),17,600,Design.INK);Design.text(body,RecordUi.preciseClock(this,entry.start,zone)+" – "+RecordUi.preciseClock(this,entry.end,zone)+" · "+entry.zone,13,400,Design.MUTED);Design.space(body,10);Design.text(body,"Sleep as Android · original CSV",13,600,Design.BROWN);Design.text(body,"Original CSV signals and annotations. SleepWell did not measure or verify them. Signal bars use source order; annotation lanes use explicit source times.",13,400,Design.MUTED);
        if(data.record.edit.start!=data.record.rawStart||data.record.edit.end!=data.record.rawEnd)Design.text(body,"The app period was edited. These original source charts are not trimmed or retimed to that edit.",12,500,Design.BROWN);
        chart(body,"Actigraphy","Original movement scale",data.signals.actigraphy,false,Design.BROWN);chart(body,"Noise","Original noise scale · not decibels",data.signals.noise,true,0xffa777df);
        if(!data.signals.events.isEmpty())timeline(body,data,zone);
        RecordUi.heading(body,"Original source summary");Design.item(body,"clock","Period duration",RecordUi.duration(entry.period),null);Design.item(body,"moon","Vendor adjusted duration",entry.netDuration==null?"Not reported":RecordUi.duration(entry.netDuration),null);Design.item(body,"info","Awake / length adjustment",entry.adjustmentMinutes==null?"Not reported":entry.adjustmentMinutes+" min",null);Design.item(body,"star","Original rating",entry.rating.toPlainString()+" / 5",null);Design.text(body,"The aggregate adjustment has no known placement. It does not become awake intervals. Fractional ratings are kept exactly here; the app's integer rating is not rounded.",12,400,Design.MUTED);if(entry.dstResolved)Design.text(body,"The period's repeated local time was resolved from Id + Hours. Sample clock labels still have no inferred date or DST offset.",12,400,Design.MUTED);
        if(!entry.note.isEmpty()){RecordUi.heading(body,"Original comment");Design.text(body,entry.note,14,400,Design.INK);}if(!data.signals.events.isEmpty()){Design.item(body,"file","Original event fields",Integer.toString(data.signals.events.size()),this::events);Design.text(body,"Every original label and timestamp is retained. Only complete supported source pairs appear on the separate annotation timeline.",12,400,Design.MUTED);}
        Design.space(body,12);Design.text(body,"Source ID: "+entry.sourceId+"\nOriginal rows SHA-256: "+entry.sha256,10,400,Design.MUTED);if(!job.message.isEmpty())Design.text(body,job.message,13,500,Design.BROWN);Design.space(body,12);Design.text(body,"Export contains the exact retained two/three CSV rows, including original comments, tags and any location hash or device/event metadata in those rows. It is one record, not a full sleep backup.",12,400,Design.MUTED);LinearLayout footer=RecordUi.footer(body);if(job.phase==SleepCsvSourceJob.Phase.WRITING||job.phase==SleepCsvSourceJob.Phase.CANCELLING){Design.button(footer,job.phase==SleepCsvSourceJob.Phase.CANCELLING?"Closing export…":"Cancel export",false,job::cancelExport).setEnabled(job.phase==SleepCsvSourceJob.Phase.WRITING);}else {Design.button(footer,"Save original record CSV",true,this::export).setEnabled(job.phase==SleepCsvSourceJob.Phase.READY);Design.button(footer,"Refresh source",false,job::load).setEnabled(!job.busy());}
    }
    private void timeline(LinearLayout body,SleepCsvSourceJob.Data data,ZoneId zone){
        RecordUi.heading(body,"Original event annotations");
        Design.text(body,"Complete source pairs only. Blank gaps are unknown; overlapping lanes retain the original annotations. These are imported labels, not SleepWell measurements.",12,400,Design.MUTED);
        RecordUi.segments(body,new String[]{"Full period","6-hour view"},timelineFull?0:1,n->{timelineFull=n==0;changed();});
        final long window=6L*60*60000;int pages=(int)((data.source.period-1)/window+1);timelinePage=Math.max(0,Math.min(timelinePage,pages-1));
        long from=timelineFull?data.source.start:data.source.start+timelinePage*window,to=timelineFull?data.source.end:Math.min(data.source.end,from+window);
        body.addView(new SleepCsvEventChart(this,data.timeline,from,to,zone,this::spanDetail),new LinearLayout.LayoutParams(-1,Design.dp(this,250)));
        Design.text(body,RecordUi.date(from,zone)+" · "+RecordUi.preciseClock(this,from,zone)+" – "+RecordUi.date(to,zone)+" · "+RecordUi.preciseClock(this,to,zone),11,400,Design.MUTED);
        if(!timelineFull&&pages>1){LinearLayout row=Design.row(this);Button before=Design.button(row,"Earlier events",false,()->{timelinePage--;changed();}),after=Design.button(row,"Later events",false,()->{timelinePage++;changed();});before.setEnabled(timelinePage>0);after.setEnabled(timelinePage+1<pages);half(before);half(after);body.addView(row);}
        Design.text(body,data.timeline.spans.size()+" complete pairs · "+data.timeline.alarms.size()+" alarm markers",12,500,Design.BROWN);
        if(data.timeline.spans.isEmpty())Design.text(body,"No complete supported pairs are available. No intervals were filled in.",13,400,Design.MUTED);
        if(data.timeline.unpaired+data.timeline.outside+data.timeline.unknown+data.timeline.duplicates+data.timeline.unreadable>0)Design.text(body,data.timeline.unpaired+" unpaired/ambiguous anchors · "+data.timeline.outside+" fields outside the original period · "+data.timeline.unknown+" other/payload labels · "+data.timeline.duplicates+" duplicate anchors · "+data.timeline.unreadable+" unreadable fields. Counts can overlap; original fields remain available below.",11,400,Design.MUTED);
        Design.button(body,"Inspect paired intervals",false,this::intervals).setEnabled(!data.timeline.spans.isEmpty());
    }
    private void intervals(){if(job.data==null||job.data.timeline.spans.isEmpty())return;int pages=(job.data.timeline.spans.size()+19)/20;intervalPage=Math.max(0,Math.min(intervalPage,pages-1));if(detail!=null)detail.dismiss();if(pages==1)showIntervals();else{String[] labels=new String[pages];for(int i=0;i<pages;i++)labels[i]="Intervals "+(i*20+1)+"–"+Math.min(job.data.timeline.spans.size(),(i+1)*20);detail=SleepPicker.choices(this,"Source interval pages",labels,intervalPage,n->{intervalPage=n;showIntervals();});}}
    private void showIntervals(){if(job.data==null)return;if(detail!=null)detail.dismiss();java.util.List<SleepCsvEvents.Span> spans=job.data.timeline.spans;int first=intervalPage*20,last=Math.min(spans.size(),first+20);if(first>=last)return;ZoneId zone=ZoneId.of(job.data.source.zone);String[] labels=new String[last-first];for(int n=first;n<last;n++){SleepCsvEvents.Span span=spans.get(n);labels[n-first]=span.lane.label+" · "+RecordUi.preciseClock(this,span.start.time,zone)+" – "+RecordUi.preciseClock(this,span.end.time,zone);}detail=SleepPicker.choices(this,"Original paired intervals",labels,-1,n->spanDetail(spans.get(first+n)));}
    private void spanDetail(SleepCsvEvents.Span span){if(detail!=null)detail.dismiss();if(job.data==null)return;ZoneId zone=ZoneId.of(job.data.source.zone);String text="Imported source annotation only. Numeric event fields are interpreted as Unix milliseconds in the saved source zone.\n\n"+Instant.ofEpochMilli(span.start.time).atZone(zone)+"\n"+Instant.ofEpochMilli(span.end.time).atZone(zone)+"\nDuration: "+(span.end.time-span.start.time)+" ms\n\nOriginal start field #"+(span.start.index+1)+":\n"+span.start.raw+"\n\nOriginal end field #"+(span.end.index+1)+":\n"+span.end.raw;detail=SleepPicker.message(this,span.lane.label+" source interval",text);}
    private void chart(LinearLayout body,String title,String units,SleepCsvFormat.Signals signals,boolean noise,int color){RecordUi.heading(body,title);Design.text(body,units,12,500,Design.MUTED);if(signals.samples.isEmpty()){Design.space(body,12);Design.text(body,signals.interpretation,14,400,Design.MUTED);return;}int pages=Math.max(1,(signals.samples.size()+SleepCsvSourceChart.PAGE-1)/SleepCsvSourceChart.PAGE),page=Math.max(0,Math.min(noise?noisePage:movementPage,pages-1));if(noise)noisePage=page;else movementPage=page;int first=page*SleepCsvSourceChart.PAGE,last=Math.min(signals.samples.size(),first+SleepCsvSourceChart.PAGE);int selected=noise?noiseSelected:movementSelected;if(selected<first||selected>=last)selected=first;final int[] cursor={selected};TextView reading=Design.text(this,"",13,500,Design.BROWN);SleepCsvSourceChart chart=new SleepCsvSourceChart(this,signals,page,color,index->{cursor[0]=index;if(noise)noiseSelected=index;else movementSelected=index;reading.setText(sample(signals,index));});chart.selected(selected);body.addView(chart,new LinearLayout.LayoutParams(-1,Design.dp(this,190)));reading.setText(sample(signals,selected));body.addView(reading);Design.text(body,"Colored dots at the baseline are measured zero. Blank columns are missing or unavailable; no lines bridge them.",11,400,Design.MUTED);Design.text(body,signals.available+" available · "+signals.missing+" unavailable · "+signals.samples.size()+" source positions",12,400,Design.MUTED);Design.text(body,signals.interpretation,12,400,Design.MUTED);
        LinearLayout inspection=Design.row(this);Button previous=Design.button(inspection,"Previous value",false,()->{int value=Math.max(first,cursor[0]-1);cursor[0]=value;if(noise)noiseSelected=value;else movementSelected=value;chart.selected(value);reading.setText(sample(signals,value));}),next=Design.button(inspection,"Next value",false,()->{int value=Math.min(last-1,cursor[0]+1);cursor[0]=value;if(noise)noiseSelected=value;else movementSelected=value;chart.selected(value);reading.setText(sample(signals,value));});half(previous);half(next);body.addView(inspection);Design.text(body,"Source positions "+(first+1)+"–"+last+" of "+signals.samples.size()+" · page "+(page+1)+" / "+pages,11,400,Design.MUTED);
        if(pages>1){LinearLayout paging=Design.row(this);Button before=Design.button(paging,"Earlier columns",false,()->{if(noise)noisePage=page-1;else movementPage=page-1;changed();}),after=Design.button(paging,"Later columns",false,()->{if(noise)noisePage=page+1;else movementPage=page+1;changed();});before.setEnabled(page>0&&!job.busy());after.setEnabled(page+1<pages&&!job.busy());half(before);half(after);body.addView(paging);}
    }
    private void half(Button button){LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(0,-2,1);lp.setMargins(Design.dp(this,3),Design.dp(this,8),Design.dp(this,3),0);button.setLayoutParams(lp);}
    private static String sample(SleepCsvFormat.Signals signal,int index){SleepCsvFormat.Sample value=signal.samples.get(index);return "Source position "+(index+1)+" · CSV column "+value.column+(value.clock.isEmpty()?"":" · label "+value.clock)+"\n"+(value.available()?"Original value: "+value.raw:value.missing+(value.raw.isEmpty()?"":" · raw "+value.raw));}
    private void events(){if(detail!=null)detail.dismiss();if(job.data==null)return;int pages=Math.max(1,(job.data.signals.events.size()+19)/20);eventPage=Math.max(0,Math.min(eventPage,pages-1));if(pages==1)showEventPage();else detail=SleepPicker.choices(this,"Source event pages",pageLabels(pages),eventPage,index->{eventPage=index;showEventPage();});}
    private String[] pageLabels(int count){String[] labels=new String[count];for(int i=0;i<count;i++)labels[i]="Events "+(i*20+1)+"–"+Math.min(job.data.signals.events.size(),(i+1)*20);return labels;}
    private void showEventPage(){if(detail!=null)detail.dismiss();java.util.List<String> events=job.data.signals.events;StringBuilder text=new StringBuilder("Original source fields; not SleepWell stage estimates.\n\n");for(int n=eventPage*20;n<Math.min(events.size(),(eventPage+1)*20);n++){text.append(n+1).append(". ").append(events.get(n)).append('\n');for(SleepCsvEvents.Event event:job.data.timeline.events)if(event.index==n&&event.inPeriod){text.append(Instant.ofEpochMilli(event.time).atZone(ZoneId.of(job.data.source.zone))).append(" · interpreted source epoch ms\n");break;}}detail=SleepPicker.message(this,"Source event fields",text.toString());}
    private void export(){if(!hasWindowFocus()||!job.choose())return;try{startActivityForResult(new Intent(Intent.ACTION_CREATE_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType("text/csv").putExtra(Intent.EXTRA_TITLE,"SleepWell-source-"+job.data.source.sourceId+".csv"),job.request);}catch(RuntimeException unavailable){job.cancelChoice();}}
    @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request!=job.request)return;if(result!=RESULT_OK||data==null){job.cancelChoice();return;}try{if(data.getClipData()!=null&&data.getClipData().getItemCount()>1){job.cancelChoice();return;}job.write(data.getData());}catch(RuntimeException invalid){job.cancelChoice();}}
    private void back(){if(job.phase==SleepCsvSourceJob.Phase.WRITING||job.phase==SleepCsvSourceJob.Phase.CHOOSING){job.cancelExport();return;}finish();}
    @android.annotation.SuppressLint("GestureBackNavigation") @Override public void onBackPressed(){back();}
    @Override public void onSaveInstanceState(Bundle state){super.onSaveInstanceState(state);state.putInt("movementPage",movementPage);state.putInt("noisePage",noisePage);state.putInt("movementSelected",movementSelected);state.putInt("noiseSelected",noiseSelected);state.putInt("eventPage",eventPage);state.putInt("timelinePage",timelinePage);state.putInt("intervalPage",intervalPage);state.putBoolean("timelineFull",timelineFull);state.putString("sourceHash",sourceHash);}
    @Override protected void onDestroy(){if(detail!=null)detail.dismiss();job.detach(this);if(!isChangingConfigurations())job.close();super.onDestroy();}
    @Override public void onWindowFocusChanged(boolean focused){super.onWindowFocusChanged(focused);if(focused)RecordUi.lightBars(this);}
}
